xhtml:div.xhtml:script:
(function () {
  "use strict";

  var endpoint = "https://ubg-site.pages.dev/app.html";
  var frame = document.getElementById("nero-app");
  var timeoutMs = 9000;
  var finished = false;

  function directFallback() {
    if (finished) return;
    finished = true;
    frame.removeAttribute("srcdoc");
    frame.src = endpoint;
  }

  function addBase(html) {
    var base = '<base href="' + endpoint.replace(/"/g, "&quot;") + '">';
    if (/<head(?:\s[^>]*)?>/i.test(html)) {
      return html.replace(/<head(?:\s[^>]*)?>/i, function (tag) {
        return tag + base;
      });
    }
    if (/<html(?:\s[^>]*)?>/i.test(html)) {
      return html.replace(/<html(?:\s[^>]*)?>/i, function (tag) {
        return tag + "<head>" + base + "</head>";
      });
    }
    return "<!doctype html><html><head>" + base +
      "</head><body>" + html + "</body></html>";
  }

  function inject(html) {
    if (finished || typeof html !== "string" || !html.trim()) {
      directFallback();
      return;
    }
    finished = true;
    frame.srcdoc = addBase(html);
  }

  if (!window.fetch) {
    directFallback();
    return;
  }

  var controller = typeof AbortController !== "undefined"
    ? new AbortController()
    : null;
  var timeout = window.setTimeout(function () {
    if (controller) controller.abort();
    directFallback();
  }, timeoutMs);

  fetch(endpoint, {
    method: "GET",
    mode: "cors",
    credentials: "omit",
    cache: "no-store",
    signal: controller ? controller.signal : undefined
  }).then(function (response) {
    if (!response.ok) throw new Error("HTTP " + response.status);
    return response.text();
  }).then(function (html) {
    window.clearTimeout(timeout);
    inject(html);
  }).catch(function () {
    window.clearTimeout(timeout);
    directFallback();
  });
})();
